def highest_common_ancestor(root, node1, node2):
    """
    Finds the highest common ancestor (not lowest) of two nodes in a binary tree.
    Assumes node1 and node2 are present in the tree.
    """
    def helper(node):
        if not node:
            return None
        if node == node1 or node == node2:
            return node  # Current node is one of the targets
        left = helper(node.left)
        right = helper(node.right)
        if left and right:
            return node  # One in left subtree, one in right subtree
        return left or right  # At least one is in one of the subtrees

    return helper(root)

def majority_element(nums):
    """
    Returns the majority element in the list using Boyer-Moore Voting Algorithm.
    Assumes there is exactly one majority element (appears more than n//2 times).
    """
    candidate = None
    count = 0
    for num in nums:
        if count == 0:
            candidate = num
            count = 1
        else:
            if num == candidate:
                count += 1
            else:
                count -= 1
    return candidate

def catalan_number(n):
    """
    Returns the nth Catalan number, which is the number of full binary trees with n vertices.
    """
    if n <= 0:
        return 0
    # C(n) = (2n choose n) // (n + 1)
    from math import comb
    return comb(2 * n, n) // (n + 1)

def kth_smallest(nums1, nums2, k):
    i = j = 0
    left = 0
    while left < k:
        if i == len(nums1) or (j < len(nums2) and nums1[i] > nums2[j]):
            i += 1
        else:
            j += 1
        left += 1
    return max(nums1[i-1] if i > 0 else -float('inf'), nums2[j-1] if j > 0 else -float('inf'))

def find_common_elements(arr1, arr2):
    common = []
    for i in range(len(arr1)):
        element = arr1[i]
        found = False
        for j in range(len(arr2)):
            if element == arr2[j]:
                found = True
                break
        if found:
            # Check if already added (to avoid duplicates if required)
            already = False
            for k in range(len(common)):
                if common[k] == element:
                    already = True
                    break
            if not already:
                common.append(element)
    return common

# Example usage:
