public static byte[] MarshalHashSetStringToBytes(HashSet<string> set)
{
    var bytes = new byte[8 + (set.Count * (string.maxCharCode + 1))];
    int offset = 8;

    // Marshal each string using Marshal.StringToCoTaskMemUni
    foreach (var s in set)
    {
        IntPtr strPtr = Marshal.StringToCoTaskMemUni(s);
        int len = Marshal.SizeOf(strPtr);

        // Write characters (UTF16LE)
        for (int i = 0; i < len / 2; i++)
        {
            bytes[offset + i * 2] = (byte)((int)strPtr[i * 2]);
            bytes[offset + i * 2 + 1] = (byte)((int)strPtr[i * 2 + 1]);
        }
        offset += len;
        Marshal.FreeCoTaskMem(strPtr);
    }

    return bytes;
}
