// Simple automatically garbage-collected linked list using smart pointers

#include <memory>

struct Node {
    int data;
    std::shared_ptr<Node> next;
};

// Constructor for convenience
std::shared_ptr<Node> make_node(int data) {
    auto node = std::make_shared<Node>();
    node->data = data;
    return node;
}

// Example usage:
int main() {
    auto head = make_node(1);
    auto second = make_node(2);
    head->next = second;
    auto third = make_node(3);
    second->next = third;

    // When 'head' goes out of scope, all nodes will be GC'd because they're shared_ptr
    return 0;
}
```

**Explanation:**  
By using `std::shared_ptr` for each node, the memory is automatically managed via reference counting. When the last reference to a node is removed (e.g., when the `head` pointer goes out of scope), the destructor is called for all nodes with no references, triggering automatic garbage collection. No manual delete or delete[] is required.

class Events {
  subscribers = {}

  subscribe(eventName, callback) {
    if (!this.subscribers[eventName]) {
      this.subscribers[eventName] = []
    }
    this.subscribers[eventName].push(callback)
  }

  unsubscribe(eventName, callback) {
    if (this.subscribers[eventName]) {
      this.subscribers[eventName] = this.subscribers[eventName].filter(c => c !== callback)
    }
  }

  trigger(eventNames, ...args) {
    for (const name of eventNames) {
      if (this.subscribers[name]) {
        this.subscribers[name].forEach(cb => cb(...args))
      }
    }
  }
}

