function getExpense(arr1, arr2, b) {
  const combined = arr1.concat(arr2);
  let minDiff = Infinity;
  let bestSum = 0;
  for (let i = 0; i < combined.length; i++) {
    for (let j = i; j < combined.length; j++) {
      const sum = combined.slice(i, j + 1).reduce((a, c) => a + c, 0);
      if (Math.abs(sum - b) < Math.abs(minDiff - b) || (Math.abs(sum - b) === Math.abs(minDiff - b) && sum >= bestSum)) {
        minDiff = Math.abs(sum - b);
        bestSum = sum;
      }
    }
  }
  return bestSum;
}
