package main

import (
    "fmt"
    "net/http"
)

type HandlerFunc func(w http.ResponseWriter, r *http.Request)

func simpleRouter() http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        switch r.Method {
        case "GET":
            handleGet(w, r)
        case "POST":
            handlePost(w, r)
        default:
            http.Error(w, "Method not allowed", 405)
        }
    })
}

func handleGet(w http.ResponseWriter, r *http.Request) {
    fmt.Fprint(w, "GET request received\n")
    if r.URL.Query().Get("name") != "" {
        fmt.Fprintln(w, "Hello, ", r.URL.Query().Get("name"))
    } else {
        fmt.Fprintln(w, "Hello, World!")
    }
}

func handlePost(w http.ResponseWriter, r *http.Request) {
    body, _ := r.Body.ReadAll()
    name := string(body) // In production, use encoding/json or form decoding
    fmt.Fprintln(w, "Received POST with name:", name)
}

func main() {
    router := simpleRouter()
    http.ListenAndServe(":8080", router)
}
```

