class CrossEntropyFunction(Function):
    @staticmethod
    def forward(ctx, activations, target):
        log_probs = F.log_softmax(activations, dim=1)  # assuming column-wise (class) dimension
        n = target.shape[0]
        loss = -torch.sum(target * log_probs, dim=1, keepdim=True) / n
        ctx.save_for_backward('loss', loss)
        return loss

    @staticmethod
    def backward(ctx, grad_output):
        loss = ctx.state['loss']
        n = grad_output.shape[0]
        log_probs = F.log_softmax(ctx activations, dim=1)
        grad_activations = grad_output.clone()
        grad_activations *= log_probs  # element-wise multiplication
        grad_activations = grad_activations / n  # divide by batch size
        ctx.restore_state()
        return grad_activations, None  # target has no parameters

class CrossEntropy(nn.Module):
    def __init__(self):
        super().__init__()
        self.func = CrossEntropyFunction.apply

    def forward(self, activations, target):
        return self.func(activations, target)
