package com.yourplugin.bounty;

import org.bukkit.Bukkit;
import org.bukkit.Economy;
import org.bukkit.command.Command;
import org.bukkit.command.CommandExecutor;
import org.bukkit.command.CommandSender;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.plugin.RegisteredServiceProvider;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.plugin.RegisteredServiceProvider;
import org.bukkit.plugin.SimplePluginManager;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

public class BountyPlugin extends JavaPlugin implements Listener {

    private static final Map<String, Double> bounties = new HashMap<>();
    private Economy econ;
    private SimplePluginManager pluginManager;

    @Override
    public void onEnable() {
        pluginManager = getServer().getPluginManager();

        // Setup Vault Economy
        if (!setupEconomy()) {
            getLogger().severe("Vault Economy plugin not found or not set up. Plugin will not function properly.");
            getServer().getPluginManager().registerEvents(this, this); // Register anyway but disable features
            return;
        }

        // Load worlds from config.yml
        YamlConfiguration config = getConfig();
        if (!config.contains("bounties.enabled")) {
            config.set("bounties.enabled", Collections.singletonList(getServer().getWorlds().get(0).getName()));
        } else {
            String[] worlds = config.getStringList("bounties.enabled");
            for (String worldName : worlds) {
                World world = getServer().getWorld(worldName);
                if (world != null) {
                    config.set(world.getName(), true);
                } else {
                    getLogger().warning("World " + worldName + " not found in server. Skipping.");
                }
            }
        }
        saveConfig();

        // Register commands
        pluginManager.registerCommand("bounty", new BountyCommand());
        pluginManager.registerCommand("add", new BountyAddCommand());

        // Register event listener
        getServer().getPluginManager().registerEvents(this, this);
    }

    private boolean setupEconomy() {
        if (getServer().getPluginManager().getPlugin("Vault") == null) {
            return false;
        }
        RegisteredServiceProvider<Economy> esp = getServer().getServicesManager().getRegistration(Economy.class);
        if (esp == null) {
            return false;
        }
        econ = esp.getProvider();
        return econ != null;
    }

    @EventHandler
    public void onPlayerDeath(PlayerDeathEvent event) {
        Player deadPlayer = event.getPlayer();
        String worldName = deadPlayer.getWorld().getName();

        // Only process in enabled worlds
        if (!isWorldEnabled(worldName)) return;

        // Get bounty for the player (default 0 if not set)
        double bounty = bounties.getOrDefault(deadPlayer.getName(), 0.0D);

        if (bounty > 0) {
            // Give the killer the bounty (if killer is online)
            Player killer = event.getKillByEntity();
            if (killer != null && killer.isOnline()) {
                double reward = bounty;
                if (econ != null && econ.has sufficient Funds(killer, reward)) {
                    econ.withdrawPlayer(killer, reward);
                    // Deduct from killer's balance (if they paid with Vault)
                }
                // Give the reward to the killer (could be handled via Vault's balance or directly)
                // For simplicity, just deduct from killer (Vault handles it)
                // Reset the dead player's bounty
                bounties.put(deadPlayer.getName(), 0.0D);
            } else {
                // If killer is offline, reward goes to server or is lost (could be improved)
                bounties.put(deadPlayer.getName(), 0.0D);
            }
        }
    }

    private boolean isWorldEnabled(String worldName) {
        YamlConfiguration config = getConfig();
        if (!config.contains("bounties.enabled")) {
            return true; // fallback
        }
        return config.getBoolean(worldName);
    }

    // Command handlers

    class BountyCommand implements CommandExecutor {
        @Override
        public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
            if (args.length < 1) {
                sender.sendMessage("Usage: /bounty <player>");
                return true;
            }
            String target = args[0];
            if (sender instanceof Player) {
                Player player = (Player) sender;
                double bounty = bounties.getOrDefault(target, 0.0D);
                if (econ != null && econ.hasSufficientFunds(player, bounty)) {
                    player.sendMessage("You will receive " + bounty + " if you kill " + target);
                } else {
                    player.sendMessage("You do not have enough money to claim this bounty.");
                }
            } else {
                sender.sendMessage("Only players can use this command.");
            }
            return true;
        }
    }

    class BountyAddCommand implements CommandExecutor {
        @Override
        public boolean onCommand(CommandSender sender, Command cmd, String label, String[] args) {
            if (args.length < 2) {
                sender.sendMessage("Usage: /bounty add <player> <amount>");
                return true;
            }
            String target = args[0];
            double amount;
            try {
                amount = Double.parseDouble(args[1]);
            } catch (NumberFormatException e) {
                sender.sendMessage("Invalid amount.");
                return true;
            }

            if (sender instanceof Player) {
                Player player = (Player) sender;
                if (econ != null) {
                    if (econ.hasSufficientFunds(player, amount)) {
                        // Check if player has enough for deduction
                        if (!bounties.containsKey(target)) {
                            bounties.put(target, 0.0D);
                        }
                        bounties.put(target, bounties.getOrDefault(target, 0.0D) + amount);

                        // Deduct from player's balance
                        econ.withdrawPlayer(player, amount);
                        player.sendMessage("Added " + amount + " to " + target + "'s bounty. You now have " + econ.getBalance(player) + ".");
                    } else {
                        player.sendMessage("You do not have enough money to add to the bounty.");
                    }
                } else {
                    sender.sendMessage("Economy plugin not set up. Cannot process this command.");
                }
            } else {
                sender.sendMessage("Only players can add bounties.");
            }
            return true;
        }
    }
}
