	nCategories   = 3 // Number of expense categories
	BudgetTotal   = 1000 // Total budget
	TargetPercent = []float64{0.4, 0.35, 0.25} // Target proportions (sum to 1)
	Weights       = []float64{1.0, 2.0, 3.0}   // Importance of each category
)

// Chromosome: slice of n real numbers (allocations)
type Chromosome []float64

// Fitness function: minimize weighted squared deviation from targets
func fitness(c Chromosome) float64 {
	alloc := make([]float64, nCategories)
	copy(alloc, c) // copy the chromosome values

	// Calculate current allocation as absolute amounts
	// (since target is percentage of total budget)
	// For each category: targetAmount = TargetPercent[i] * BudgetTotal
	// But we'll optimize for proportion first, then scale to total budget
	// Let's optimize for proportions first (sum to 1), then scale up
	probs := make([]float64, nCategories)
	for i := range alloc {
		probs[i] = alloc[i] / float64(BudgetTotal) // normalize to 0..1
	}
 targets := make([]float64, nCategories)
	for i := range targets {
		targets[i] = TargetPercent[i]
	}
	// Objective: minimize Σ weight[i] * (probs[i] - targets[i])^2
	sum := 0.0
	for i := range probs {
		sum += Weights[i] * (probs[i] - targets[i]) * (probs[i] - targets[i])
	}
	// Return negative for maximization (since GA maximizes fitness)
	return -sum
}

