func selectParent(population []Chromosome, t int) Chromosome {
	// Randomly pick t best
	m := make([]Chromosome, t)
	for i := range m {
		// Index of best so far
		mi := 0
		for j := 1; j < len(m); j++ {
			if fitness(m[j]) > fitness(m[mi]) {
