    void update(double t) {
        double dt = t - last_pre_spike_time;
        if (dt < 20.0) { // Short interval: LTP
            delta_w += 0.01 * dt;
        } else if (dt > 100.0) { // Long interval: LTD
            delta_w -= 0.005 * dt;
        }
        weight += delta_w;
        last_pre_spike_time = t;
        // Optionally apply mod_func here
    }
