Here is a complete Java program that simulates rolling two dice, calculates the theoretical probabilities, runs multiple simulations, and prints a formatted table with both theoretical and empirical probabilities for sums 2 through 12. The code uses arrays to store and display the results, and uses `DecimalFormat` for proper formatting.

```java
import java.util.Random;
import java.text.DecimalFormat;

public class SumOfTwoDiceSimulator {
    public static void main(String[] args) {
        // Number of simulations
        int[] simulations = {36, 500, 10000};
        String[] labels = {"36", "500", "10,000"};
        double[][] empirical = new double[11][simulations.length]; // Index 0 unused (sums 2-12)
        double[][] theoretical = {
            {0, 0, 0.0278, 0.0556, 0.0833, 0.1111, 0.1389, 0.1667, 0.1667, 0.1389, 0.1111, 0.0833}, // P(2) to P(12)
            // (Actually calculated below for precision, but can be computed on the fly)
        };

        // First, compute theoretical probabilities for sums 2 to 12
        int[] countsTheo = new int[13]; // indices 0..12, use 2..12
        for (int s = 2; s <= 12; s++) {
            int ways = 0;
            for (int d1 = 1; d1 <= 6; d1++) {
                int d2 = s - d1;
                if (d2 >= 1 && d2 <= 6) {
                    ways++;
                }
            }
            countsTheo[s] = ways;
        }
        int total = 36; // 6*6 possible outcomes
        for (int s = 2; s <= 12; s++) {
            theoretical[s - 2] = countsTheo[s] / total;
        }

        // Now, run simulations
        for (int i = 0; i < simulations.length; i++) {
            int numRolled = simulations[i];
            int[] counts = new int[13]; // 0..12, use 2..12
            Random rand = new Random();
            for (int j = 0; j < numRolled; j++) {
                int d1 = rand.nextInt(6) + 1;
                int d2 = rand.nextInt(6) + 1;
                int sum = d1 + d2;
                counts[sum] += 1;
            }
            // Compute empirical probabilities
            for (int s = 2; s <= 12; s++) {
                empirical[s - 2][i] = counts[s] / (double) numRolled;
            }
        }

        // Set up DecimalFormat for 4 decimal places
        DecimalFormat df = new DecimalFormat("#.####");

        // Print header
        System.out.println("Sum of 2 Dice Simulator");
        System.out.println("X\tP(X) Theoretical\tP(X) Empirical(36)\tP(X) Empirical(500)\tP(X) Empirical(10,000)");
        System.out.println("------------------------------------------------------------");
        for (int s = 2; s <= 12; s++) {
            String xStr = String.valueOf(s);
            // Determine tab width for X based on max length (e.g., 12 is 2 chars, so 4 spaces)
            int xTab = 4; // all sums are 1 or 2 digits, 4 is safe
            String pTheo = df.format(theoretical[s - 2]);
            String p36 = df.format(empirical[s - 2][0]);
            String p500 = df.format(empirical[s - 2][1]);
            String p10000 = df.format(empirical[s - 2][2]);
            // For alignment, pad the probabilities to 4 decimals
            System.out.format("%-" + xTab + "d\t%8s\t%8s\t%8s\t%10s\n",
                s,
                pTheo,
                p36,
                p500,
                p10000
            );
        }
    }
}
