```java
import java.io.*;
import java.net.*;
import java.util.Scanner;

public class PA14A_Server {
    public static void main(String[] args) throws IOException {
        ServerSocket serverSocket = new ServerSocket(8080);
        System.out.println("Loan server started on port 8080");

        while (true) {
            Socket clientSocket = serverSocket.accept();
            BufferedReader in = new BufferedReader(
                new InputStreamReader(clientSocket.getInputStream()));
            DataOutputStream out = new DataOutputStream(clientSocket.getOutputStream());

            // Read the three values from the client
            String line = in.readLine();
            String[] parts = line.trim().split("\\s+");
            double annualRate = Double.parseDouble(parts[0]);
            int years = Integer.parseInt(parts[1]);
            double loanAmount = Double.parseDouble(parts[2]);

            // Calculations as per the formulas
            double monthlyInterestRate = annualRate / 1200.0;
            double monthlyPayment = loanAmount * monthlyInterestRate /
                (1 - Math.pow(1 + monthlyInterestRate, -years * 12));
            double totalPayment = monthlyPayment * years * 12;

            // Send results back to client as two doubles
            out.writeDouble(monthlyPayment);
            out.writeDouble(totalPayment);

            out.close();
            in.close();
            clientSocket.close();
        }
    }
}
```

