function CSockIO.MakeRequestMsg(const FF: TForeignFunctions; DataLength: Integer; Data: PAny): PForMsgHdr; var
begin
  // Get the application instance
  var App: CRemTstApp; var GotApp: Boolean = False;
  try
    App := AfxGetApp();
    GotApp := True;
  except
    App := nil;
  end;

  // Calculate total message length
  var MsgLen: Integer = sizeof(ForMsgHdr) + DataLength;

  // Allocate memory for the header
  Result := PForMsgHdr.Create(AllocMem(Word(MsgLen)));
  Result^.Function := FF;
  Result^.DataLength := DataLength;
  Result^.Status := -1;
  Result^.UserData := App?.GetNewSeqNo();

  // Copy data if provided
  if (Data <> nil) and (DataLength > 0) then
    CopyMem(Result + 1, Data, DataLength);
end;

