% Main script for Car ABS Simulation in MATLAB

clear; clc; close all;

%% Parameters
T_s = 0.01; % Sampling time (seconds)
N = 1000;   % Number of time steps

Braking_Torque = 300; % Nm (maximum braking torque)
Max_Brake_Ramp = 50; % Nm/s (max rate of brake pressure increase)
Max_Slip = 0.15;    % [rad] max wheel slip
Saturation = 400;   % Nm (tire-road friction limit)
mu_max = 0.7;      % Maximum friction coefficient
g = 9.81;          % Gravity m/s^2

%% State Variables (initialization)
Brake_P = 0;        % Brake pressure (arbitrary units)
Brake_Rate = 0;     % Current brake pressure ramp rate (Nm/s)
Wheel_Torque = 0;    % Torque applied to wheel (Nm)
Wheel_RPM = 2000;    % Initial wheel speed (RPM)
Wheel_Vel = (Wheel_RPM * 2 * pi / 60) / 1000; % m/s (from RPM)
Slip = 0;            % Initial slip (rad)
ABSCycle = 0;        % ABS cycle state (0=normal, 1=decelerating, 2=increasing)
Time = 0;

%% Functions

function Torque = Braking_Torque(P)
    % Simple linear relation between brake pressure and torque
    % Assume F = k * P, k = friction coefficient * radius^2 * mu
    % For simulation, linear up to saturation
    k = 0.05; % Nm/(brake pressure unit)
    Torque = min(min(P * k, Saturation), Braking_Torque);
end

function Ramp = RampFunction(t, t0, T_ramp, direction)
    % Ramp up or down between 0 and T_ramp
    if direction == 1 % increasing
        Ramp = min(T_ramp * t / t0, T_ramp);
    else % decreasing
        Ramp = max(0, T_ramp - T_ramp * t / t0);
    end
end

function Slip = SlipFunction(V_w, V_r)
    % Simple linear tire model: V_r = R * omega_w * (1 + mu * Slip)
    % V_w = vehicle velocity, V_r = road reference velocity (usually 0 for braking)
    % omega_w = wheel angular velocity (rad/s)
    R = 0.033; % wheel radius m
    mu = 0.5 + 0.3*abs(ABSCycle-1); % dynamic friction (varies with ABS)
    if V_r == 0
        % No slip reference (braking on stationary road)
        Slip = (V_w - 0) / (R * (omega_w));
    else
        % For simplicity, assume V_r = 0 (braking)
        Slip = (V_w - 0) / (R * (omega_w));
    end
    Slip = max(min(Slip, Max_Slip), -Max_Slip); % Clamp slip
end

function [NextState, Stopped] = ABScycle(ABSCycle, Slip, Wheel_Torque, Brake_Rate)
    % Simple 3-state ABS cycle (0=normal, 1=decel, 2=accel)
    % Detect if wheel is over-braked (high slip)
    if Slip > 0.1 && Wheel_Torque < 200
        % Too much braking, reduce
        NextState = 1; % decelerating (release brake)
        Stopped = false;
    elseif Slip < -0.1 && Wheel_Torque > 200
        % Too little braking, increase
        NextState = 2; % increasing (apply more brake)
        Stopped = false;
    else
        % Within tolerance, maintain
        NextState = ABSCycle;
        Stopped = false;
    end
end

%% Simulation Loop

for t = 1:N
    dt = T_s;
    % 1. Compute desired braking torque (user input or model)
    % For demo, apply constant max braking
    Desired_Torque = Braking_Torque(Brake_P);

    % 2. Tire model: relate slip to wheel dynamics
    % For simplicity, assume wheel inertia is negligible (model only slip response)
    % In real case, use wheel inertia and angular momentum equations

    % 3. Compute desired brake pressure to achieve desired torque
    % P = Torque / k (from Braking_Torque function)
    Desired_P = Desired_Torque / 0.05;

    % 4. Ramp brake pressure (smooth control)
    Ramp_Dir = (ABSCycle == 0 && Desired_P > Brake_P) || (ABSCycle == 1 && Desired_P < Brake_P) || (ABSCycle == 2 && Desired_P > Brake_P);
    Ramp = RampFunction(t, t-1, Max_Brake_Ramp, Ramp_Dir);

    % 5. Update brake pressure (with hysteresis or filter if needed)
    Brake_P = Ramp * dt + Brake_P * (1 - dt/T_s);

    % 6. Compute actual wheel torque
    Wheel_Torque = Braking_Torque(Brake_P);

    % 7. Compute wheel slip (using tire model)
    Wheel_omega = (Wheel_RPM * 2 * pi) / (60 * 1000); % rad/s
    Slip = SlipFunction(Wheel_Vel, 0);

    % 8. ABS cycle update
    [ABSCycle, Stopped] = ABScycle(ABSCycle, Slip, Wheel_Torque, Brake_Rate);
    Brake_Rate = Ramp; % current rate of change of brake pressure

    % 9. Update wheel velocity (simple model: v = omega * R, with slip)
    % For simplicity, assume no wheel inertia (only slip effect)
    % v_w = (R * Wheel_omega) * (1 + mu * Slip)  (simple linear model)
    mu = 0.5 + 0.3*abs(ABSCycle-1);
    V_w_new = (R * Wheel_omega) * (1 + mu * Slip);
    Wheel_Vel = V_w_new * dt + Wheel_Vel * (1 - dt/T_s);

    % 10. Store or plot results (optional)
    % Time vector
    Time = t * T_s;
    % Store for plotting: [Time, Slip, Wheel_Torque, Brake_P]
end

% --- Plotting (optional) ---
figure;
subplot(2,1,1);
plot(Time, Slip, 'b');
xlabel('Time (s)'); ylabel('Wheel Slip (rad)');
title('ABS Wheel Slip Over Time');

subplot(2,1,2);
plot(Time, Wheel_Torque, 'r');
xlabel('Time (s)'); ylabel('Wheel Torque (Nm)');
title('ABS Torque Control');
