    $relPath = Join-Path $startingDir -ChildPath ($folder -Recurse)

    # Navigate to the folder
    Set-Location -Path $relPath

    # Checkout origin/main, fetch, reset hard
    & "dotnet restore" -nologfile
    & "dotnet build" -r origin/main -nologfile
    & "git fetch --all --prune" -nologfile
    & "git reset --hard origin/main" -nologfile

    # Check if TK/14278_TM-13 branch exists
    $branch = "TK/14278_TM-13"
    if (git branch -a | Select-String -Pattern "$branch\ " -CaseInsensitive) {
        # Branch exists, reset to main
        & "git checkout $branch" -nologfile
        & "git merge main --no-ff --allow-unrelated-histories" -nologfile
    } else {
        # Create new branch
        & "git checkout -b $branch" -nologfile
    }

    # Find and replace inMvcBuilderExtensions.cs
    $file = Join-Path . "MvcBuilderExtensions.cs"
    if (Test-Path $file) {
        $content = Get-Content $file -Raw
        $replaceFrom = "o.Select().Filter().OrderBy().Count().Expand().SetMaxTop(100);"
        $replaceTo   = "$replaceFrom
                        o.TimeZone = TimeZoneInfo.Utc;"
        $updated = $content -replace $replaceFrom, $replaceTo
        Set-Content $file -Value $updated -Encoding UTF8
    }

    # Update NuGet packages in main project (name ends with .Solutions or .csproj with "Ewl.Platform.Common.Api")
    $mainProj = Get-ChildItem -Path . -Filter '*Ewl.Platform.Common.Api*.csproj' -ErrorAction SilentlyContinue | ? { $_.Name -like 'Ewl.Platform.Common.Api*' }
    if ($mainProj) {
        $mainProj | ForEach-Object {
            $nugetCmd = "nuget set --version 1.0.0 -Source https://www.nuget.org/api/v3-flatcontainer/ -nupkg -k"
            & $nugetCmd -ArgumentList ($_.FullName, "-version", "1.0.0") -Wait
        }
    }

    # Update NuGet packages in storage projects (name ends with .Storage)
    $storageProj = Get-ChildItem -Path . -Filter '*Ewl.Platform.Common.Storage*.csproj' -ErrorAction SilentlyContinue
    if ($storageProj) {
        $storageProj | ForEach-Object {
            $nugetCmd = "nuget set --version 1.0.0 -Source https://www.nuget.org/api/v3-flatcontainer/ -nupkg -k"
            & $nugetCmd -ArgumentList ($_.FullName, "-version", "1.0.0") -Wait
        }
    }

    # Run tests
    & "dotnet test" -nologfile
}

# Return to starting directory
Set-Location -Path $startingDir
