    public int chunkHeight = 64; // Number of height layers per chunk (adjust as needed)
    public float renderDistance = 100f; // Max world distance to render chunks
    public GameObject chunkPrefab; // Assign the prefab for generated chunk meshes (optional)

    private Dictionary<Vector2Int, TerrainChunk> loadedChunks = new Dictionary<Vector2Int, TerrainChunk>();
    private Dictionary<Vector2Int, GameObject> chunkMeshes = new Dictionary<Vector2Int, GameObject>();

