    }

    void LoadInitialView()
    {
        // Clear old chunks
        loadedChunks.Clear();
        chunkMeshes.Clear();

        // Find the world bounds of the terrain
        Vector3 bounds = terrain.bounds;
        bounds.center -= terrain.transform.position; // Center in world space
        float halfSize = bounds.size.x / 2f;

        // Calculate the grid of chunks that are within render distance
        float maxWorldDist = renderDistance;
        int minChunkX = Mathf.CeilToInt(-maxWorldDist / chunkSize);
        int maxChunkX = Mathf.FloorToInt(maxWorldDist / chunkSize) + 1;
        int minChunkY = Mathf.CeilToInt(-maxWorldDist / (chunkSize * chunkHeight));
        int maxChunkY = Mathf.FloorToInt(maxWorldDist / (chunkSize * chunkHeight));

        for (int x = minChunkX; x <= maxChunkX; x++)
        for (int y = minChunkY; y <= maxChunkY; y++)
        {
            Vector2Int chunkPos = new Vector2Int(x, y);
            Vector2Int localPos = new Vector2Int(
                (int)(chunkPos.x * chunkSize),
                (int)(chunkPos.y * chunkSize * chunkHeight)
            );
            Vector2 center = new Vector2(
                bounds.min.x + (chunkPos.x + 0.5f) * chunkSize,
                bounds.min.y + (chunkPos.y + 0.5f) * chunkSize * chunkHeight
            );
            float dist = Vector3.Distance(center, playerPosition);
            if (dist <= renderDistance)
            {
                GenerateOrLoadChunk(chunkPos, localPos);
            }
            else
            {
                // Out of view: schedule unload in a few frames if needed
                // (Unloading logic can be added here if performance critical)
            }
        }
    }

    void GenerateOrLoadChunk(Vector2Int globalChunkPos, Vector2Int localChunkPos)
    {
        if (loadedChunks.ContainsKey(globalChunkPos))
            return; // Already loaded

        // Generate or load the chunk mesh (example: generate if needed, else load from asset)
        // For demo, we'll just create a placeholder mesh if you have a prefab
        GameObject chunkMesh;
        if (chunkPrefab != null)
        {
            chunkMesh = Instantiate(chunkPrefab, new Vector3(
                globalChunkPos.x * chunkSize + chunkSize / 2f,
                localChunkPos.y * chunkSize * chunkHeight + chunkHeight / 2f,
                0), Quaternion.identity);
            chunkMesh.transform.SetParent(transform, false);
            chunkMesh.name = $"Chunk_{globalChunkPos}";
            chunkMeshes[globalChunkPos] = chunkMesh;
        }
        else
        {
            // Here you would generate the procedural mesh using Vista's API
            // For now, just create a placeholder
            chunkMesh = new GameObject("ProceduralChunk_" + globalChunkPos);
            chunkMesh.transform.SetParent(transform, false);
            chunkMeshes[globalChunkPos] = chunkMesh;
        }

        // Assign the terrain chunk data to this chunk
        TerrainChunk chunk = new TerrainChunk();
        chunk.globalPos = globalChunkPos;
        chunk.localPos = localChunkPos;
        chunk.mesh = chunkMesh;
        loadedChunks[globalChunkPos] = chunk;

        // Optionally, enable/disable rendering for this chunk based on distance
        chunkMesh.transform.enabled = (Vector3.Distance(
            chunkMesh.transform.position,
            playerPosition) <= renderDistance);
    }

    void OnDrawGizmos()
    {
        // Optional: visualize loaded chunks in the editor
        foreach (var entry in loadedChunks)
        {
            Gizmos.color = Color.yellow;
            Gizmos.DrawWireSphere(entry.value.transform.position, 0.05f);
        }
    }

    // Unload chunks that are out of view (simple approach: disable and schedule unload)
    void UpdateOutOfViewChunks()
    {
        lastPlayerPosition = playerPosition;
        List<Vector2Int> toUnload = new List<Vector2Int>();

        foreach (var pos in loadedChunks.Keys)
        {
            TerrainChunk chunk = loadedChunks[pos];
            GameObject mesh = chunk.mesh;
            if (mesh != null && mesh.transform)
            {
                float dist = Vector3.Distance(mesh.transform.position, playerPosition);
                if (dist > renderDistance)
                {
                    toUnload.Add(pos);
                }
            }
        }

        foreach (Vector2Int pos in toUnload)
        {
            if (loadedChunks.ContainsKey(pos))
            {
                TerrainChunk chunk = loadedChunks[pos];
                chunk.mesh?.enabled = false;
                chunk.mesh = null;
                loadedChunks.Remove(pos);
                chunkMeshes.Remove(pos);
